#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Submits the podcast feeds to the podcast directories, one directory at a time,
# and records each approved show as a PodcastDirectoryListing in the production
# database (over SSH, on the host deploy/deploy.sh uses). Feeds already listed
# are skipped, so stop any time and run it again. The directories' own steps are
# in README.md › "Publishing to podcast directories"; keep the two in step.
#
# It never submits to Apple, Spotify, YouTube, or Amazon itself: those need the
# owner signed in. Podcast Index is the one automated submission.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
API="https://api.dailyoffice2019.com"
OWNER_EMAIL="feedback@dailyoffice2019.com"
PROMOTED_FLAG="app/src/helpers/podcasts.js"
DIRECTORY_ORDER=(podcast-index apple spotify youtube amazon iheart pocket-casts deezer)
SSH_HOST=$(sed -n 's/^SSH_HOST=//p' "$ROOT/deploy/deploy.sh")
SERVER_DIR=$(sed -n 's/^SERVER_DIR=//p' "$ROOT/deploy/deploy.sh")
# One SSH connection, reused by every manage.py call.
SSH_OPTS=(-o ConnectTimeout=15 -o ControlMaster=auto -o "ControlPath=$HOME/.ssh/cm-%C" -o ControlPersist=5m)
# Feeds submitted but not yet approved (platform, slug, date), so a later run can say so.
STATE_FILE="${PODCAST_WIZARD_STATE:-$HOME/.local/state/dailyoffice2019/podcast-submissions.tsv}"

usage() {
  cat <<EOF
Submit the podcast feeds to the podcast directories and record each approved listing.

  scripts/podcast-directories.sh [--local] [DIRECTORY ...]

DIRECTORY is any of: ${DIRECTORY_ORDER[*]}
(default: all of them, in that order). Feeds already listed are skipped, so stop
any time and run it again, or do one directory at a time.

  --local   read and record listings in your development database instead of
            production, to try the wizard out (submits nothing to Podcast Index)
EOF
}

# directory_key NAME — the directory a command-line name means.
directory_key() {
  case "$(printf '%s' "$1" | tr 'A-Z_' 'a-z-')" in
    podcast-index | podcastindex) echo podcast-index ;;
    apple | apple-podcasts) echo apple ;;
    spotify) echo spotify ;;
    youtube | youtube-music) echo youtube ;;
    amazon | amazon-music | audible) echo amazon ;;
    iheart | iheartradio) echo iheart ;;
    pocket-casts | pocketcasts) echo pocket-casts ;;
    deezer) echo deezer ;;
    *) return 1 ;;
  esac
}

# directory KEY — set NAME, PLATFORM (PodcastDirectoryListing's), PORTAL, what
# an approved show's link looks like (SHOW_URL), and whether it's OPTIONAL.
directory() {
  OPTIONAL=""
  case "$1" in
    podcast-index) NAME="Podcast Index" PLATFORM=podcast_index PORTAL="https://api.podcastindex.org" \
      SHOW_URL="https://podcastindex.org/podcast/…" ;;
    apple) NAME="Apple Podcasts" PLATFORM=apple PORTAL="https://podcastsconnect.apple.com" \
      SHOW_URL="https://podcasts.apple.com/us/podcast/…" ;;
    spotify) NAME="Spotify" PLATFORM=spotify PORTAL="https://creators.spotify.com" \
      SHOW_URL="https://open.spotify.com/show/…" ;;
    youtube) NAME="YouTube Music" PLATFORM=youtube_music PORTAL="https://studio.youtube.com" \
      SHOW_URL="https://music.youtube.com/playlist?list=…" ;;
    amazon) NAME="Amazon Music" PLATFORM=amazon PORTAL="https://podcasters.amazon.com" \
      SHOW_URL="https://music.amazon.com/podcasts/…" ;;
    iheart) NAME="iHeartRadio" PLATFORM=iheart PORTAL="https://www.iheart.com/content/submit-your-podcast/" \
      SHOW_URL="https://www.iheart.com/podcast/…" OPTIONAL=1 ;;
    pocket-casts) NAME="Pocket Casts" PLATFORM=pocket_casts PORTAL="https://pocketcasts.com/submit/" \
      SHOW_URL="https://pca.st/…" OPTIONAL=1 ;;
    deezer) NAME="Deezer" PLATFORM=deezer PORTAL="https://podcasters.deezer.com" \
      SHOW_URL="https://www.deezer.com/show/…" OPTIONAL=1 ;;
  esac
}

# submission_steps — what to do in the directory for one feed (README.md).
submission_steps() {
  case "$PLATFORM" in
    apple)
      step "In Podcasts Connect choose + › New Show › Add a show with an RSS feed."
      step "Paste the feed URL, check the preview and validation, and choose Publish."
      note "Review usually takes a few days: mark it submitted (w) and come back for the link." ;;
    spotify)
      step "In Spotify for Creators choose Add a new show › Find an existing show › Somewhere else."
      step "Paste the feed URL."
      step "Enter the 8-digit code Spotify emails to $OWNER_EMAIL." ;;
    youtube_music)
      step "In YouTube Studio choose Create › New podcast › Submit RSS feed."
      step "Paste the feed URL and verify with the code emailed to $OWNER_EMAIL."
      step "Import all episodes. They start out private: review and publish them in Studio."
      note "YouTube makes static-image videos from the cover art." ;;
    amazon)
      step "At podcasters.amazon.com choose Add your podcast and give it the feed URL." ;;
    *)
      step "On the $NAME submission page, give it the feed URL." ;;
  esac
}

die() {
  printf '\n  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2
  shift
  local line
  for line in "$@"; do note "$line" >&2; done
  printf '\n' >&2
  exit 1
}

# copy TEXT — put TEXT on the clipboard, when there's a way to.
copy() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# manage ARGS... — run manage.py on the production server (locally with --local).
manage() {
  if (( LOCAL )); then
    (cd "$ROOT/site" && PODCAST_BASE_URL="$API" PYTHONWARNINGS=ignore "$PYTHON" manage.py "$@" </dev/null)
  else
    ssh "${SSH_OPTS[@]}" "$SSH_HOST" \
      "cd $SERVER_DIR/site && . ../env/bin/activate && python manage.py $(printf '%q ' "$@")" </dev/null
  fi
}

# load_missing PLATFORM — the feeds not yet listed there, into SLUGS, TITLES, URLS.
load_missing() {
  local rows slug title url
  SLUGS=() TITLES=() URLS=()
  rows=$(manage podcast_submission_checklist --missing "$1") ||
    die "Couldn't read the listings with podcast_submission_checklist."
  while IFS=$'\t' read -r slug title url; do
    [[ -n "$slug" ]] || continue
    SLUGS+=("$slug") TITLES+=("$title") URLS+=("$url")
  done <<<"$rows"
}

# submitted_on PLATFORM SLUG — the day the feed was marked submitted, if it was.
submitted_on() {
  [[ -f "$STATE_FILE" ]] || return 0
  awk -F'\t' -v p="$1" -v s="$2" '$1 == p && $2 == s { day = $3 } END { if (day) print day }' "$STATE_FILE"
}

mark_submitted() {
  mkdir -p "$(dirname "$STATE_FILE")"
  printf '%s\t%s\t%s\n' "$1" "$2" "$(date +%Y-%m-%d)" >>"$STATE_FILE"
}

# feed_header I N — like stage(), for one feed inside the current stage.
feed_header() {
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s · feed %s of %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$NAME" "$1" "$2" "$RESET"
  if [[ -n "$LAST" ]]; then printf '  %s%s%s\n' "$GREEN" "$LAST" "$RESET"; fi
  LAST=""
}

# submit_feeds — one screen per feed in SLUGS: its URL, the steps, and a
# prompt for the approved show's link.
submit_feeds() {
  local i n=${#SLUGS[@]} reply since output
  for ((i = 0; i < n; i++)); do
    while true; do
      feed_header $((i + 1)) "$n"
      printf '\n  %s%s%s\n  %s\n' "$BOLD" "${TITLES[i]}" "$RESET" "${URLS[i]}"
      if copy "${URLS[i]}"; then note "(feed URL copied to the clipboard)"; fi
      printf '\n'
      since=$(submitted_on "$PLATFORM" "${SLUGS[i]}")
      if [[ -n "$since" ]]; then
        say "You submitted this feed on $since. If it never went through, submit it again:"
      fi
      submission_steps
      note "Verification emails go to $OWNER_EMAIL."
      printf '\n'
      say "Once $NAME approves it, paste the show's link ($SHOW_URL):"
      note "w = submitted, waiting for approval · Enter = skip for now · q = stop $NAME"
      printf '  %s›%s ' "$BOLD" "$RESET"
      read -r reply || reply=q
      case "$reply" in
        "") break ;;
        w | W)
          mark_submitted "$PLATFORM" "${SLUGS[i]}"
          LAST="✓ ${TITLES[i]}: submitted, waiting for approval."
          break ;;
        q | Q) return ;;
        http://* | https://*)
          if output=$(manage record_podcast_listing "${SLUGS[i]}" "$PLATFORM" "$reply" 2>&1); then
            RECORDED=$((RECORDED + 1))
            LAST="✓ ${output##*$'\n'}"
            break
          fi
          warn "${output##*$'\n'}"
          pause "Press Enter to try again" ;;
        *) pause "Paste a link starting with https://, or type w or q. Press Enter to try again" ;;
      esac
    done
  done
}

# ── Stage: preflight ───────────────────────────────────────────────────────
preflight() {
  local response code feeds slug title url episodes
  local -a empty=() down=()
  stage "Check that the feeds are live"
  say "Directories fetch a feed the moment it's submitted, so each one must be public"
  say "with at least one episode."
  printf '\n'
  response=$(curl -s --max-time 30 -w '\n%{http_code}' "$API/api/v1/podcasts") || response=$'\n000'
  code=${response##*$'\n'}
  [[ "$code" == 200 ]] || die "$API/api/v1/podcasts returned $code, so the feeds aren't live yet." \
    "Deploy the podcasts branch and build the first episodes (README.md › Podcasts), then run this again."
  feeds=$(printf '%s' "${response%$'\n'*}" | python3 -c '
import json, sys
for feed in json.load(sys.stdin)["feeds"]:
    print(feed["slug"], feed["title"], feed["feed_url"], feed["episode_count"], sep="\t")
') || die "$API/api/v1/podcasts didn't return the podcast catalog."
  FEED_COUNT=0
  while IFS=$'\t' read -r slug title url episodes; do
    FEED_COUNT=$((FEED_COUNT + 1))
    (( episodes > 0 )) || empty+=("$title")
    code=$(curl -s -o /dev/null --max-time 30 -w '%{http_code}' "$url") || code=000
    [[ "$code" == 200 ]] || down+=("$url returned $code")
  done <<<"$feeds"
  if (( ${#empty[@]} )); then
    die "These feeds have no episodes yet, and directories turn down an empty feed:" "${empty[@]}" \
      "Build them on the server with build_podcast_episodes (README.md › Podcasts), then run this again."
  fi
  if (( ${#down[@]} )); then
    die "These feeds aren't reachable:" "${down[@]}"
  fi
  step "✓ $FEED_COUNT feeds are live, each with episodes."

  if (( LOCAL )); then
    warn "Practice run (--local): listings go to your development database, not production."
  else
    manage record_podcast_listing --help >/dev/null ||
      die "Couldn't run the podcast commands on $SSH_HOST." \
        "Check that you can ssh there (deploy/deploy.sh uses the same host) and that the" \
        "deployed code has record_podcast_listing."
    step "✓ Connected to the production server; approved listings are recorded there."
  fi
  printf '\n'
  say "Each directory lists every feed as its own show, so each one gets $FEED_COUNT submissions."
  say "Verification codes and emails go to $OWNER_EMAIL: keep that inbox open."
  pause "Press Enter to continue"
}

# ── Stage: Podcast Index (automated) ───────────────────────────────────────
podcast_index_stage() {
  local missing
  directory podcast-index
  stage "$NAME"
  load_missing "$PLATFORM"
  missing=${#SLUGS[@]}
  say "Podcast Index feeds Podverse, Fountain, Castamatic, and other Podcasting 2.0 apps."
  say "$((FEED_COUNT - missing)) of $FEED_COUNT feeds are listed there."
  if (( missing == 0 )); then
    pause "Nothing to do here. Press Enter to continue"
    return
  fi
  say "It's the one automated submission: notify_podcast_directories --add-to-podcast-index"
  say "submits every feed and records each listing."
  printf '\n'
  if (( LOCAL )); then
    warn "Practice run (--local): not submitting to Podcast Index."
    pause "Press Enter to continue"
    return
  fi
  if ! confirm "Submit all $FEED_COUNT feeds to Podcast Index now?"; then
    SKIPPED+=("$NAME: $missing feeds not listed yet (scripts/podcast-directories.sh podcast-index)")
    return
  fi
  local has_key='from django.conf import settings; print(bool(settings.PODCAST_INDEX_API_KEY and settings.PODCAST_INDEX_API_SECRET))'
  if [[ "$(manage shell -v 0 -c "$has_key")" == True ]]; then
    say "Using the Podcast Index API key already set on the server."
    manage notify_podcast_directories --add-to-podcast-index || warn "Podcast Index didn't take every feed."
  else
    say "The server has no Podcast Index API key, so you'll need a free one."
    open_url "$PORTAL"
    step "Sign up for an API key, then copy its key and secret."
    ask_secret PODCAST_INDEX_API_KEY "Paste the API key:"
    ask_secret PODCAST_INDEX_API_SECRET "Paste the API secret:"
    # On stdin, so the key stays out of the server's process list. Not saved anywhere.
    printf '%s\n%s\n' "$PODCAST_INDEX_API_KEY" "$PODCAST_INDEX_API_SECRET" |
      ssh "${SSH_OPTS[@]}" "$SSH_HOST" "read -r PODCAST_INDEX_API_KEY && read -r PODCAST_INDEX_API_SECRET &&
        export PODCAST_INDEX_API_KEY PODCAST_INDEX_API_SECRET && cd $SERVER_DIR/site &&
        . ../env/bin/activate && python manage.py notify_podcast_directories --add-to-podcast-index" ||
      warn "Podcast Index didn't take every feed."
  fi
  load_missing "$PLATFORM"
  if (( ${#SLUGS[@]} )); then
    SKIPPED+=("$NAME: ${#SLUGS[@]} feeds not listed yet (scripts/podcast-directories.sh podcast-index)")
  fi
  pause "Press Enter to continue"
}

# ── Stage: one directory, submitted by hand ────────────────────────────────
directory_stage() {
  local key=$1 missing waiting=0 before i
  directory "$key"
  stage "$NAME"
  load_missing "$PLATFORM"
  missing=${#SLUGS[@]}
  say "$((FEED_COUNT - missing)) of $FEED_COUNT feeds are listed on $NAME."
  if (( missing == 0 )); then
    pause "Nothing to do here. Press Enter to continue"
    return
  fi
  for ((i = 0; i < missing; i++)); do
    if [[ -n "$(submitted_on "$PLATFORM" "${SLUGS[i]}")" ]]; then waiting=$((waiting + 1)); fi
  done
  if (( waiting )); then say "$waiting submitted earlier: paste their links once $NAME approves them."; fi
  if [[ -n "$OPTIONAL" ]]; then
    note "Optional: Apple Podcasts and Podcast Index already reach most other apps."
  fi
  printf '\n'
  say "For each of the $missing feeds you'll see its feed URL (copied to your clipboard)"
  say "and what to do, then paste the show's $NAME link once it's approved."
  if ! confirm "Work on $NAME now?"; then
    SKIPPED+=("$NAME: $missing feeds not listed yet (scripts/podcast-directories.sh $key)")
    return
  fi
  open_url "$PORTAL"
  pause "Sign in if asked, then press Enter for the first feed"
  before=$RECORDED
  submit_feeds
  missing=$((missing - (RECORDED - before)))
  if (( missing )); then
    SKIPPED+=("$NAME: $missing feeds not listed yet (scripts/podcast-directories.sh $key)")
  fi
}

# ── Stage: what's next ─────────────────────────────────────────────────────
wrap_up() {
  local core_missing=0 entry platform name
  stage "What's next"
  for entry in "apple:Apple Podcasts" "spotify:Spotify" "youtube_music:YouTube Music"; do
    platform=${entry%%:*} name=${entry#*:}
    load_missing "$platform"
    say "$name: $((FEED_COUNT - ${#SLUGS[@]})) of $FEED_COUNT feeds listed"
    core_missing=$((core_missing + ${#SLUGS[@]}))
  done
  printf '\n'
  if (( core_missing )); then
    say "The app keeps its links to the Podcasts page off until all three list every feed."
  elif grep -q 'PODCASTS_PROMOTED = true' "$ROOT/$PROMOTED_FLAG"; then
    step "✓ All three list every feed, and the app already links to the Podcasts page."
  else
    step "✓ Apple Podcasts, Spotify, and YouTube Music list every feed."
    say "The app doesn't link to the Podcasts page yet. To turn on the menu entry and the"
    say "audio player's link, set PODCASTS_PROMOTED to true in $PROMOTED_FLAG, then deploy."
    SKIPPED+=("Turn on the app's links to the Podcasts page: PODCASTS_PROMOTED = true in $PROMOTED_FLAG")
  fi
  pause "Press Enter to finish"
}

LOCAL=0
SELECTED=()
for arg in "$@"; do
  case "$arg" in
    -h | --help) usage; exit 0 ;;
    --local) LOCAL=1 ;;
    *)
      key=$(directory_key "$arg") || { printf 'Unknown directory: %s\n\n' "$arg" >&2; usage >&2; exit 2; }
      SELECTED+=("$key") ;;
  esac
done
if (( ${#SELECTED[@]} == 0 )); then SELECTED=("${DIRECTORY_ORDER[@]}"); fi
if (( LOCAL )); then
  STATE_FILE="${STATE_FILE%.tsv}-local.tsv"
  if [[ -z "${PYTHON:-}" ]]; then
    PYTHON=python
    if [[ -x "$ROOT/site/.venv/bin/python" ]]; then PYTHON="$ROOT/site/.venv/bin/python"; fi
  fi
fi
RECORDED=0
LAST=""
FEED_COUNT=0

TOTAL_STAGES=$((${#SELECTED[@]} + 2))

cd "$ROOT"
banner "Submit the podcasts to the podcast directories"
preflight
for key in "${SELECTED[@]}"; do
  if [[ "$key" == podcast-index ]]; then podcast_index_stage; else directory_stage "$key"; fi
done
wrap_up
finish
if (( RECORDED )); then
  note "Recorded $RECORDED listing(s) this run; the landing page shows them within a few minutes."
  printf '\n'
fi
